  "manufacturers": [
    {
      "name": "Ohaus Corporation",
      "address_lines": ["19A Chapin Road, 07058 Pine Brook", "USA"]
    }
  ],
  "certified_type": {
    "category": "Non-automatic weighing instrument",
    "type_designations": ["AV…-C", "AS…-C"],
    "module_designation": null,
    "description": "Non-automatic electromechanical weighing instrument with or without lever works; compact weighing instrument with built-in display, keyboard and data-interface. The weighing ranges comprising Max, verification scale intervals, number of verification scale intervals and scale intervals may be selected considering the limiting values in Table 1; this also applies for weighing results indicated in carat."
  },
  "characteristics": {
    "type_level": {
      "tare_balancing_range": {
        "value": {"min": null, "max": 100},
        "unit_symbol": "%",
        "unit_id": null,
        "footnote_markers": []
      },
      "temperature_range": {
        "value": {"min": 10, "max": 30},
        "unit_symbol": "°C",
        "unit_id": null,
        "footnote_markers": []
      }
    },
    "config_level": [
      {
        "attribute": "maximum_capacity",
        "axis": "accuracy_class",
        "values": [
          {"condition": "I", "value": {"min": 65, "max": 260}, "unit_symbol": "g", "unit_id": null, "footnote_markers": []},
          {"condition": "II", "value": {"min": 210, "max": 4100}, "unit_symbol": "g", "unit_id": null, "footnote_markers": []}
        ]
      },
      {
        "attribute": "verification_scale_interval_e",
        "axis": "accuracy_class",
        "values": [
          {"condition": "I", "value": 0.001, "unit_symbol": "g", "unit_id": null, "footnote_markers": []},
          {"condition": "II", "value": {"min": 0.01, "max": 0.1}, "unit_symbol": "g", "unit_id": null, "footnote_markers": []}
        ]
      },
      {
        "attribute": "scale_interval_d",
        "axis": "accuracy_class",
        "values": [
          {"condition": "I", "value": 0.0001, "unit_symbol": "g", "unit_id": null, "footnote_markers": []},
          {"condition": "II", "value": {"min": 0.001, "max": 0.01}, "unit_symbol": "g", "unit_id": null, "footnote_markers": []}
        ]
      },
      {
        "attribute": "number_of_verification_scale_intervals_n",
        "axis": "accuracy_class",
        "values": [
          {"condition": "I", "value": {"min": null, "max": 260000}, "unit_symbol": null, "unit_id": null, "footnote_markers": []},
          {"condition": "II", "value": {"min": null, "max": 61000}, "unit_symbol": null, "unit_id": null, "footnote_markers": []}
        ]
      }
    ]
  },
  "matrix_tables": [
    {
      "name": "Table 1 – Limiting values for selectable weighing ranges",
      "columns": ["attribute", "accuracy_class_I", "accuracy_class_II"],
      "rows": [
        {"attribute": "max", "accuracy_class_I": "65 g … 260 g", "accuracy_class_II": "210 g … 4100 g"},
        {"attribute": "verification_scale_interval_e", "accuracy_class_I": "0.001 g", "accuracy_class_II": "0.01 g … 0.1 g"},
        {"attribute": "scale_interval_d", "accuracy_class_I": "0.0001 g", "accuracy_class_II": "0.001 g … 0.01 g"},
        {"attribute": "number_of_verification_scale_intervals_n", "accuracy_class_I": "≤ 260000", "accuracy_class_II": "≤ 61000"},
        {"attribute": "tare_balancing_range", "accuracy_class_I": "≤ 100 % of Max", "accuracy_class_II": "≤ 100 % of Max"},
        {"attribute": "temperature_range", "accuracy_class_I": "10 °C … 30 °C", "accuracy_class_II": "10 °C … 30 °C"}
      ],
      "description": "Weighing ranges comprising Max, verification scale intervals, number of verification scale intervals and scale intervals may be selected considering the limiting values; this also applies for weighing results indicated in carat. Tare-balancing range and temperature range apply to both accuracy classes.",
      "footnotes": []
    }
  ],
  "recommendation": {
    "id": "R76-1",
    "edition": 1992,
    "amendment": "Amendment 1 (1994)",
    "accuracy_classes": ["I", "II"]
  },
  "test_reports": [
    {"id": "1.12-4020116", "pages": 8, "role": "type_evaluation_report"},
