    {"id": "1.12-4020116/3", "pages": 47, "role": "test_report"},
    {"id": "1.12-4020116/4", "pages": 6, "role": "test_report"}
  ],
  "revision_history": [
    {
      "revision": "2",
      "date": "2007-02-28",
      "changes": "Issued because the maximum number of verification scale intervals was increased to 61000 for class (II) instruments. Conformity established in Report N° 1.12-4020116, Revision 2 and by tests described in Test Report N° 1.12-4020116/5; the test results of the former Test Reports No. 1.12-4020116/1, No. 1.12-4020116/2, No. 1.12-4020116/3 and No. 1.12-4020116/4 remain valid."
    }
  ]
}
